using Microsoft.Extensions.Logging;

namespace X3Code.Repository;

/// <summary>
/// The log events the unit of work writes. Generated by the LoggerMessage source generator, so a
/// call costs nothing while the level is switched off - the arguments are not even boxed.
/// </summary>
/// <remarks>
/// Everything goes through <see cref="ILogger"/>, the abstraction. This library brings no sink and
/// no configuration; where the events end up is entirely the consuming application's decision.
/// </remarks>
internal static partial class UnitOfWorkLog
{
    [LoggerMessage(EventId = 1000, Level = LogLevel.Debug,
        Message = "Unit of work opened a transaction on {Context}.")]
    internal static partial void TransactionOpened(ILogger logger, string context);

    [LoggerMessage(EventId = 1001, Level = LogLevel.Debug,
        Message = "Unit of work joined a transaction that was already open on {Context}. Only the outermost scope decides.")]
    internal static partial void JoinedOpenTransaction(ILogger logger, string context);

    [LoggerMessage(EventId = 1002, Level = LogLevel.Debug,
        Message = "Unit of work committed.")]
    internal static partial void Committed(ILogger logger);

    [LoggerMessage(EventId = 1003, Level = LogLevel.Debug,
        Message = "Unit of work discarded without completing it, everything since it was opened is rolled back.")]
    internal static partial void Discarded(ILogger logger);

    [LoggerMessage(EventId = 1004, Level = LogLevel.Warning,
        Message = "An inner unit of work was left without completing it. The surrounding one can no longer be committed.")]
    internal static partial void AbandonedByInnerScope(ILogger logger);

    [LoggerMessage(EventId = 1005, Level = LogLevel.Debug,
        Message = "Unit of work retried by the execution strategy.")]
    internal static partial void Retried(ILogger logger);
}
